const customer = await db.customer.findUnique({ where: { id: userId } });
const tickets = await db.ticket.findMany({ where: { customerId: userId } });
const policies = await loadAllPolicyDocuments();

const prompt = [systemInstructions, JSON.stringify(customer), JSON.stringify(tickets), policies]
  .join("\n\n");

logger.info({ prompt }, "assistant request");
const reply = await model.complete({ prompt });
return reply;
